import sys
from math import gcd

def construct_relatively_prime_graph(n, m):
    if m < n - 1 or m > n * (n - 1) // 2:
        return "Impossible"

    edges = []

    # Create a spanning tree with n-1 edges
    for i in range(2, n + 1):
        edges.append((1, i))

    # Add remaining edges while maintaining relative primality
    current_edge_count = n - 1
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if current_edge_count >= m:
                break
            if gcd(i, j) == 1:
                edges.append((i, j))
                current_edge_count += 1

    return "Possible", edges

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
